CREATE TABLE IF NOT EXISTS skills_catalog (id INT NOT NULL PRIMARY KEY, document MEDIUMTEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS skills_provider (id INT NOT NULL PRIMARY KEY, document TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS skills_usage (user_id VARCHAR(64) NOT NULL, day VARCHAR(10) NOT NULL, count INT NOT NULL DEFAULT 0, PRIMARY KEY (user_id, day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
